CREATE TABLE `ops_purchase_letters` (`id` text PRIMARY KEY NOT NULL, `seq` integer DEFAULT 0 NOT NULL, `number` text NOT NULL, `status` text DEFAULT 'final' NOT NULL, `letter_date` text NOT NULL, `supplier_name` text NOT NULL, `contact_name` text, `contact_phone` text, `supplier_address` text, `items` text DEFAULT '[]' NOT NULL, `show_prices` integer DEFAULT 0 NOT NULL, `delivery_to` text, `needed_by` text, `receiver_name` text, `receiver_phone` text, `payment` text, `payment_days` integer, `note` text, `iso_keys` text DEFAULT '[]' NOT NULL, `signer_id` integer, `signer_name` text, `signer_title` text, `created_by` integer, `created_by_name` text, `created_at` integer DEFAULT (unixepoch()) NOT NULL, `updated_at` integer DEFAULT (unixepoch()) NOT NULL);
CREATE UNIQUE INDEX `ops_pl_number_uq` ON `ops_purchase_letters` (`number`);
CREATE INDEX `ops_pl_supplier_idx` ON `ops_purchase_letters` (`supplier_name`);
